import{d as t,N as a,i as o,l as i}from"./chunks/framework.YjmuzLiw.js";const m=JSON.parse('{"title":"FAQ","description":"","frontmatter":{"title":"FAQ","outline":"deep"},"headers":[],"relativePath":"en/rich-text/faq.md","filePath":"en/rich-text/faq.md","lastUpdated":1778951341000}'),n={name:"en/rich-text/faq.md"};function d(r,e,l,s,c,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="is-this-suitable-for-npm-package-documentation" tabindex="-1">Is this suitable for npm package documentation <a class="header-anchor" href="#is-this-suitable-for-npm-package-documentation" aria-label="Permalink to &quot;Is this suitable for npm package documentation&quot;">​</a></h2><p>Yes. This site is already structured like a product documentation site and can continue to grow with navigation, version notes, and demos.</p><h2 id="what-is-the-difference-between-preview-mode-and-editable-false" tabindex="-1">What is the difference between <code>preview</code> mode and <code>editable=false</code> <a class="header-anchor" href="#what-is-the-difference-between-preview-mode-and-editable-false" aria-label="Permalink to &quot;What is the difference between `preview` mode and `editable=false`&quot;">​</a></h2><p><code>editable=false</code> mainly disables editing, while <code>mode=&quot;preview&quot;</code> switches the component into a dedicated read-only preview shell with better reading-oriented layout behavior.</p><h2 id="what-happens-if-whitelist-props-are-omitted" tabindex="-1">What happens if whitelist props are omitted <a class="header-anchor" href="#what-happens-if-whitelist-props-are-omitted" aria-label="Permalink to &quot;What happens if whitelist props are omitted&quot;">​</a></h2><p>All built-in options remain enabled by default. Once you pass a list, only the listed items remain visible and usable.</p><h2 id="which-documenttype-should-rich-text-use" tabindex="-1">Which <code>documentType</code> Should Rich Text Use <a class="header-anchor" href="#which-documenttype-should-rich-text-use" aria-label="Permalink to &quot;Which `documentType` Should Rich Text Use&quot;">​</a></h2><p>Use <code>documentType: &#39;rich&#39;</code> with the unified collaboration service. <code>word</code> is reserved for a future dedicated Word component.</p><p>All clients in the same room must use the same <code>field</code>; for normal one-file-one-editor use, keep it as <code>content</code>.</p><h2 id="why-not-initialize-collaboration-from-modelvalue" tabindex="-1">Why Not Initialize Collaboration From <code>modelValue</code> <a class="header-anchor" href="#why-not-initialize-collaboration-from-modelvalue" aria-label="Permalink to &quot;Why Not Initialize Collaboration From `modelValue`&quot;">​</a></h2><p>In collaboration mode, the Y.Doc/Yjs fragment is authoritative. The editor does not write <code>modelValue</code> into an empty collaborative fragment by default.</p><p>If the backend already has a Yjs snapshot, do not pass <code>initializeContent: true</code>. For a brand-new empty room, first confirm that this client owns initialization, then pass <code>initializeContent: true</code> and <code>initialContent</code>.</p>',13)])])}const u=t(n,[["render",d]]);export{m as __pageData,u as default};
